CREATE TYPE public.filing_portal_role AS ENUM ('regulator', 'demo_regulator');
CREATE TABLE public.filing_portal_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.filing_portal_role NOT NULL DEFAULT 'demo_regulator');
GRANT SELECT ON public.filing_portal_roles TO authenticated;
GRANT ALL ON public.filing_portal_roles TO service_role;
ALTER TABLE public.filing_portal_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own portal role" ON public.filing_portal_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_filing_regulator() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.filing_portal_roles WHERE user_id = auth.uid() AND role = 'regulator'); $$;
REVOKE ALL ON FUNCTION public.is_filing_regulator() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_filing_regulator() TO authenticated, service_role;
CREATE FUNCTION public.assign_demo_filing_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.filing_portal_roles(user_id, role) VALUES (NEW.id, 'demo_regulator') ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER assign_demo_filing_role AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_demo_filing_role();
CREATE TABLE public.form_fc_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), company text NOT NULL, period text NOT NULL, filed_on date NOT NULL, officer text NOT NULL, authority text NOT NULL, simulation boolean NOT NULL DEFAULT true CHECK (simulation = true), recorded_at timestamptz NOT NULL DEFAULT now(), transfer_snapshot jsonb NOT NULL DEFAULT '[]'::jsonb, submission_kind text NOT NULL DEFAULT 'Form FC' CHECK (submission_kind = 'Form FC'));
GRANT SELECT, INSERT ON public.form_fc_records TO authenticated;
GRANT ALL ON public.form_fc_records TO service_role;
ALTER TABLE public.form_fc_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own demos or shared regulator register" ON public.form_fc_records FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.is_filing_regulator());
CREATE POLICY "Append signed in filing records" ON public.form_fc_records FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.filing_portal_roles WHERE user_id = auth.uid()));
CREATE FUNCTION public.validate_form_fc_record() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Filing records are append-only'; END IF; IF NEW.filed_on > CURRENT_DATE THEN RAISE EXCEPTION 'Filing date cannot be in the future'; END IF; IF length(trim(NEW.company)) NOT BETWEEN 1 AND 500 OR length(trim(NEW.officer)) NOT BETWEEN 1 AND 100 OR length(trim(NEW.authority)) NOT BETWEEN 1 AND 100 OR NEW.period !~ '^[A-Za-z]+ [0-9]{4}$' OR jsonb_typeof(NEW.transfer_snapshot) <> 'array' THEN RAISE EXCEPTION 'Invalid filing details'; END IF; NEW.recorded_at := now(); RETURN NEW; END; $$;
CREATE TRIGGER protect_form_fc_records BEFORE INSERT OR UPDATE OR DELETE ON public.form_fc_records FOR EACH ROW EXECUTE FUNCTION public.validate_form_fc_record();
CREATE INDEX form_fc_company_period_time ON public.form_fc_records(company, period, recorded_at DESC);
COMMENT ON TABLE public.form_fc_records IS 'Secure demonstration records only; not official RBI or AD-bank confirmations. Append-only with retained transfer snapshot.';